#include "dsp/call.inc"
.SECTION/PM seg_pmco;
.GLOBAL _test_callback;
.EXTERN _sp_callback;
.EXTERN _sp_port_record;
_test_callback:
    DK_CALL(_sp_callback, _test_cb_back);
    JUMP _test_return;
.EXTERN _test_return;
.GLOBAL _sp_open;
_sp_open:
    DK_ENTER(1);
    DK_SAVE(2, R3);
    R0 = DM(_test_open_calls);
    R0 = R0 + 1;
    DM(_test_open_calls) = R0;
    DM(_test_open_arg0) = R4;
    DM(_test_open_arg1) = R8;
    DM(_test_open_state) = R12;
    R0 = DM(1, I6);
    DM(_test_open_size) = R0;
    I4 = DM(2, I6);
    R0 = _sp_port_record;
    DM(0, I4) = R0;
    R0 = DM(_test_open_result);
    DK_RETADDR;
    NOP; NOP; NOP;
    DK_LEAVE(R3, 2);
.GLOBAL _sp_set_callback;
_sp_set_callback:
    DK_ENTER(1);
    DK_SAVE(2, R3);
    R0 = DM(_test_setcb_calls);
    R0 = R0 + 1;
    DM(_test_setcb_calls) = R0;
    DM(_test_setcb_handle) = R4;
    DM(_test_setcb_fn) = R8;
    DM(_test_setcb_context) = R12;
    DK_RETADDR;
    NOP; NOP; NOP;
    DK_LEAVE(R3, 2);
.GLOBAL _sp_submit;
_sp_submit:
    DK_ENTER(1);
    DK_SAVE(2, R3);
    R0 = DM(_test_submit_calls);
    R0 = R0 + 1;
    DM(_test_submit_calls) = R0;
    DM(_test_submit_handle) = R4;
    DM(_test_submit_arg2) = R12;
    R0 = DM(1, I6);
    DM(_test_submit_config) = R0;
    I4 = R8;
    R0 = DM(0, I4);
    DM(_test_desc0) = R0;
    R0 = DM(1, I4);
    DM(_test_desc1) = R0;
    R0 = DM(2, I4);
    DM(_test_desc2) = R0;
    R0 = DM(3, I4);
    DM(_test_desc3) = R0;
    R0 = DM(4, I4);
    DM(_test_desc4) = R0;
    R0 = DM(5, I4);
    DM(_test_desc5) = R0;
    R0 = DM(6, I4);
    DM(_test_desc6) = R0;
    R0 = 0xdeadbeef;
    DM(2, I4) = R0;
    R0 = DM(_test_submit_result);
    DK_RETADDR;
    NOP; NOP; NOP;
    DK_LEAVE(R3, 2);
.SECTION/DM seg_dmda;
